class MedianFinder {
    private PriorityQueue<Integer> lo = new PriorityQueue<>(Collections.reverseOrder()); // smaller half, max on top
    private PriorityQueue<Integer> hi = new PriorityQueue<>();                            // larger half, min on top

    public MedianFinder() {}

    public void addNum(int num) {
        lo.offer(num);
        hi.offer(lo.poll());          // push the max of lo into hi
        if (hi.size() > lo.size()) {  // keep lo >= hi in size
            lo.offer(hi.poll());
        }
    }

    public double findMedian() {
        if (lo.size() > hi.size()) return lo.peek();
        return (lo.peek() + hi.peek()) / 2.0;
    }
}

class ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}

public ListNode mergeKLists(ListNode[] lists) {
    PriorityQueue<ListNode> pq = new PriorityQueue<>((a, b) -> a.val - b.val);
    for (ListNode node : lists) {
        if (node != null) pq.offer(node);
    }
    ListNode dummy = new ListNode(0);
    ListNode tail = dummy;
    while (!pq.isEmpty()) {
        ListNode node = pq.poll();
        tail.next = node;
        tail = node;
        if (node.next != null) pq.offer(node.next);
    }
    return dummy.next;
}

public double[] medianSlidingWindow(int[] nums, int k) {
    Comparator<Integer> byVal = (a, b) ->
        nums[a] != nums[b] ? Integer.compare(nums[a], nums[b]) : Integer.compare(a, b);
    TreeSet<Integer> lo = new TreeSet<>(byVal.reversed()); // smaller half, max at first()
    TreeSet<Integer> hi = new TreeSet<>(byVal);            // larger half, min at first()
    int n = nums.length;
    double[] ans = new double[n - k + 1];
    for (int i = 0; i < n; i++) {
        // insert index i, keeping lo balanced and >= hi in size
        lo.add(i);
        hi.add(lo.first());
        lo.remove(lo.first());
        if (hi.size() > lo.size()) {
            lo.add(hi.first());
            hi.remove(hi.first());
        }
        // remove the index leaving the window
        if (i >= k) {
            int out = i - k;
            if (!lo.remove(out)) hi.remove(out);
            if (lo.size() < hi.size()) {
                lo.add(hi.first());
                hi.remove(hi.first());
            } else if (lo.size() > hi.size() + 1) {
                hi.add(lo.first());
                lo.remove(lo.first());
            }
        }
        if (i >= k - 1) {
            ans[i - k + 1] = (k % 2 == 1)
                ? (double) nums[lo.first()]
                : ((double) nums[lo.first()] + (double) nums[hi.first()]) / 2.0;
        }
    }
    return ans;
}

public int[] topKFrequent(int[] nums, int k) {
    Map<Integer, Integer> count = new HashMap<>();
    for (int x : nums) count.merge(x, 1, Integer::sum);
    PriorityQueue<Integer> heap = new PriorityQueue<>((a, b) -> count.get(a) - count.get(b));
    for (int num : count.keySet()) {
        heap.offer(num);
        if (heap.size() > k) heap.poll();   // drop least frequent
    }
    int[] res = new int[k];
    for (int i = k - 1; i >= 0; i--) res[i] = heap.poll();
    return res;
}

public int[] topKFrequent(int[] nums, int k) {
    Map<Integer, Integer> count = new HashMap<>();
    for (int x : nums) count.merge(x, 1, Integer::sum);
    List<Integer>[] buckets = new List[nums.length + 1];
    for (Map.Entry<Integer, Integer> e : count.entrySet()) {
        int f = e.getValue();
        if (buckets[f] == null) buckets[f] = new ArrayList<>();
        buckets[f].add(e.getKey());
    }
    int[] res = new int[k];
    int idx = 0;
    for (int f = buckets.length - 1; f >= 0 && idx < k; f--) {
        if (buckets[f] == null) continue;
        for (int num : buckets[f]) {
            res[idx++] = num;
            if (idx == k) break;
        }
    }
    return res;
}

public int leastInterval(char[] tasks, int n) {
    int[] freq = new int[26];
    for (char t : tasks) freq[t - 'A']++;
    int maxFreq = 0;
    for (int f : freq) maxFreq = Math.max(maxFreq, f);
    int countMax = 0;
    for (int f : freq) if (f == maxFreq) countMax++;
    int frames = (maxFreq - 1) * (n + 1) + countMax;
    return Math.max(frames, tasks.length);
}

public int leastInterval(char[] tasks, int n) {
    int[] freq = new int[26];
    for (char t : tasks) freq[t - 'A']++;
    PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
    for (int f : freq) if (f > 0) pq.offer(f);
    int time = 0;
    while (!pq.isEmpty()) {
        int cycle = n + 1;
        List<Integer> temp = new ArrayList<>();
        int done = 0;
        while (cycle > 0 && !pq.isEmpty()) {
            int f = pq.poll();
            if (f > 1) temp.add(f - 1);
            done++;
            cycle--;
        }
        for (int f : temp) pq.offer(f);
        time += pq.isEmpty() ? done : n + 1; // no idle needed on the last block
    }
    return time;
}

public String reorganizeString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) freq[c - 'a']++;
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[1] - a[1]); // [charIdx, count]
    for (int i = 0; i < 26; i++) {
        if (freq[i] == 0) continue;
        if (freq[i] > (s.length() + 1) / 2) return "";
        pq.offer(new int[]{i, freq[i]});
    }
    StringBuilder sb = new StringBuilder();
    int[] prev = null;
    while (!pq.isEmpty()) {
        int[] cur = pq.poll();
        sb.append((char) ('a' + cur[0]));
        cur[1]--;
        if (prev != null && prev[1] > 0) pq.offer(prev); // re-enable the char held last step
        prev = cur;
    }
    return sb.toString();
}

public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
    int n = profits.length;
    int[][] projects = new int[n][2];
    for (int i = 0; i < n; i++) {
        projects[i][0] = capital[i];
        projects[i][1] = profits[i];
    }
    Arrays.sort(projects, (a, b) -> a[0] - b[0]);
    PriorityQueue<Integer> maxProfit = new PriorityQueue<>(Collections.reverseOrder());
    int i = 0;
    for (int c = 0; c < k; c++) {
        while (i < n && projects[i][0] <= w) maxProfit.offer(projects[i++][1]);
        if (maxProfit.isEmpty()) break;
        w += maxProfit.poll();
    }
    return w;
}

public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums1.length == 0 || nums2.length == 0 || k == 0) return res;
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) ->
        Long.compare((long) nums1[a[0]] + nums2[a[1]], (long) nums1[b[0]] + nums2[b[1]]));
    for (int i = 0; i < nums1.length && i < k; i++) pq.offer(new int[]{i, 0});
    while (k-- > 0 && !pq.isEmpty()) {
        int[] cur = pq.poll();
        int i = cur[0], j = cur[1];
        res.add(Arrays.asList(nums1[i], nums2[j]));
        if (j + 1 < nums2.length) pq.offer(new int[]{i, j + 1});
    }
    return res;
}

public int[] smallestRange(List<List<Integer>> nums) {
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]); // [value, listIdx, elemIdx]
    int curMax = Integer.MIN_VALUE;
    for (int i = 0; i < nums.size(); i++) {
        int v = nums.get(i).get(0);
        pq.offer(new int[]{v, i, 0});
        curMax = Math.max(curMax, v);
    }
    int[] best = new int[]{-100000, 100000}; // widest possible range
    while (true) {
        int[] cur = pq.poll();
        int v = cur[0], li = cur[1], ei = cur[2];
        if (curMax - v < best[1] - best[0]) {
            best[0] = v;
            best[1] = curMax;
        }
        if (ei + 1 == nums.get(li).size()) break; // this list is done; cannot improve
        int next = nums.get(li).get(ei + 1);
        curMax = Math.max(curMax, next);
        pq.offer(new int[]{next, li, ei + 1});
    }
    return best;
}

public int maxPerformance(int n, int[] speed, int[] efficiency, int k) {
    int[][] eng = new int[n][2];
    for (int i = 0; i < n; i++) {
        eng[i][0] = efficiency[i];
        eng[i][1] = speed[i];
    }
    Arrays.sort(eng, (a, b) -> b[0] - a[0]); // efficiency descending
    PriorityQueue<Integer> minSpeed = new PriorityQueue<>();
    long speedSum = 0, best = 0;
    for (int[] e : eng) {
        minSpeed.offer(e[1]);
        speedSum += e[1];
        if (minSpeed.size() > k) speedSum -= minSpeed.poll(); // drop smallest speed
        best = Math.max(best, speedSum * (long) e[0]);
    }
    return (int) (best % 1000000007L);
}

public int[] getOrder(int[][] tasks) {
    int n = tasks.length;
    int[][] t = new int[n][3];
    for (int i = 0; i < n; i++) {
        t[i][0] = tasks[i][0];
        t[i][1] = tasks[i][1];
        t[i][2] = i;
    }
    Arrays.sort(t, (a, b) -> a[0] - b[0]); // by enqueue time
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) ->
        a[1] != b[1] ? a[1] - b[1] : a[2] - b[2]); // shortest processing, then smallest index
    int[] res = new int[n];
    long time = 0;
    int i = 0, idx = 0;
    while (idx < n) {
        while (i < n && t[i][0] <= time) pq.offer(t[i++]);
        if (pq.isEmpty()) {
            time = t[i][0]; // jump to next arrival
            continue;
        }
        int[] cur = pq.poll();
        time += cur[1];
        res[idx++] = cur[2];
    }
    return res;
}
